import {calculateMcdOperating as engine,allocateMcdCommon} from './mcd-financial-engine.js';
import {MCD_MESSAGES} from './mcd-messages.js';
const finite=x=>typeof x==='number'&&Number.isFinite(x),object=x=>!!x&&typeof x==='object'&&!Array.isArray(x);
export const MCD_DRAFT_ERROR='MCD requires its complete dated 11-period model and finite explicit inputs. Invalid inputs are retained; valuation is withheld.';
const fail=(cause)=>{const message=/WACC|wacc/.test(cause?.message??'')?MCD_MESSAGES.waccBounds[0]:/capex|finance.lease.*investment/i.test(cause?.message??'')?MCD_MESSAGES.investmentBounds[0]:/allocation policy|policy basis|basis amount/.test(cause?.message??'')?MCD_MESSAGES.invalid[0]:MCD_DRAFT_ERROR;throw Object.assign(Error(message),{status:'invalid_assumptions',enterprise:null,equity:null,perShare:null,current_target:null,current_upside:null,cause});};
export function mcdDraftIssues(d){return d?.ticker==='MCD'&&(d.schemaVersion!==1||d.forecastHorizonYears!==11||d.timing?.mode!=='origin'||d.timing?.asOf!=='2026-10-19'||d.timing?.stubFCFF!==null||d.funding_certified===true||!Object.hasOwn(d,'mcdPolicy')||['current_target','currentPriceTarget','current_price_target','current_upside'].some(k=>d[k]!==undefined&&d[k]!==null))?[MCD_DRAFT_ERROR]:[];}
export function mcdContext(d){
 const r=incrementalRecord('MCD');
 if(d?.ticker!=='MCD'||!incrementalIdentityValid(d)||mcdDraftIssues(d).length||!Array.isArray(d.annual)||d.annual.length!==11||Object.keys(d.annual).length!==11||!object(d.bridgeInputs)||Object.keys(d.bridgeInputs).length)fail();
 const c=d.selectedIncrementalScenario?r.alternatives.find(a=>a.name===d.selectedIncrementalScenario)?.annualCase:r.annualCase;if(!c)fail();
 const annual=d.annual.map((row,i)=>{if(!object(row)||Object.keys(row).length!==7||Object.keys(row).some(k=>!['year','period','revenue','margin','taxRate','reinvestment','wacc'].includes(k))||row.year!==i+1||row.period!==c.annual[i].period||!['revenue','margin','taxRate','reinvestment','wacc'].every(k=>finite(row[k])))fail();return Object.fromEntries(['revenue','margin','taxRate','reinvestment','wacc'].map(k=>[k,row[k]]));});
 if(!object(d.terminal)||Object.keys(d.terminal).length!==5||Object.keys(d.terminal).some(k=>!['growth','margin','taxRate','roic','wacc'].includes(k)))fail();
 try{const operating=engine(r.sourceInputs,c.sourceScenario,{annual,terminal:d.terminal}),allocation=allocateMcdCommon(r.sourceInputs,operating,d.mcdPolicy);return {r,c,operating,allocation};}catch(error){fail(error);}
}
export function calculateMcdOperating(d){
 const {r,operating:v,allocation}=mcdContext(d);let prior=d.anchor.revenue,cumulative=0,trough=0;
 const rows=v.rows.map((row,i)=>{const full=row.period_revenue+(i===0?r.sourceInputs.observed_h1_2026.revenue:0),delta=full-prior,growth=full/prior-1;prior=full;cumulative+=row.fcff;trough=Math.min(trough,cumulative);return {...d.annual[i],...row,fullFiscalRevenue:full,growth,ebit:row.period_core_ebit,tax:row.period_core_ebit*row.cash_tax_rate,discountFactor:row.discount_factor,pv:row.pv_fcff,cumulativeFCFF:cumulative,derivedSalesCapital:row.reinvestment?delta/row.reinvestment:null,enteredReinvestment:d.annual[i].reinvestment,requiredInvestment:null,investmentFloorTopUp:0,mcdDatedCore:true};});
 return {ticker:'MCD',currency:'USD',informationAsOf:d.informationAsOf,discountOrigin:d.discountOrigin,rows,terminal:{...v.terminal,fcffGrowth:v.terminal_fcff_vs_2036_fcff},forecastPV:v.explicit_period_pv,terminalPV:v.terminal_pv,enterprise:v.core_operating_ev,terminalShare:v.terminal_ev_fraction,peakEconomicDeficit:Math.max(0,-trough),negativeFCFFYears:rows.filter(x=>x.fcff<0).length,warnings:[r.prose.scope.en,r.prose.leases.en,r.prose.next.en,r.prose.terminal.en],mcdAllocation:allocation,classification:r.prose.scope.en,current_target:null,current_upside:null,currentPriceTarget:null,funding_certified:false,currentValuationEligible:false,historicalBacktestEligible:false};
}
export function calculateMcdBridge(d,enterprise,options={}){
 const {r,operating:v,allocation:a}=mcdContext(d);
 if(Object.keys(options).some(k=>!['calculationDate','outputCurrency','securityBasis','informationAsOf'].includes(k))||options.calculationDate&&options.calculationDate!=='2026-06-30'||options.outputCurrency&&options.outputCurrency!=='USD'||options.securityBasis&&options.securityBasis!=='common'||options.informationAsOf&&options.informationAsOf!==d.informationAsOf||!finite(enterprise)||Math.abs(enterprise-v.core_operating_ev)>Math.max(1e-8,Math.abs(enterprise)*1e-10))fail();
 const eligible=finite(a.dated_per_share_allocation),reason=d.mcdPolicy===null?MCD_MESSAGES.none[0]:MCD_MESSAGES.withheld[0];
 return {ticker:'MCD',modelId:r.identity.version,currency:'USD',moneyUnit:'millions',enterprise,operatingEV:enterprise,status:eligible?'conditional':'operating-only',eligible,perShare:a.dated_per_share_allocation,rawPerShare:a.dated_per_share_allocation,flooredPerShare:a.dated_per_share_allocation,equity:eligible?a.conditional_june_equity_value:null,current_target:null,current_upside:null,currentPriceTarget:null,current_price_target:null,currentQuote:null,unconditionalPerShare:null,funding_certified:false,currentCapitalVerified:false,priceComparisonEligible:false,asKnownBacktestEligible:false,claimRepricedPerTrial:false,allocationLabel:r.prose.scope.en,classification:r.prose.scope.en,referenceDate:'2026-06-30',capitalReferenceDate:'2026-06-30',shareReferenceDate:'2026-06-30',discountOrigin:d.discountOrigin,calculationDate:'2026-06-30',informationAsOf:d.informationAsOf,securityBasis:r.bridge.shareBasis,claimCompleteness:r.bridge.claimCompleteness,sources:[{url:r.bridge.sourceUrl,date:'2026-06-30'}],warnings:[r.prose.scope.en,r.prose.claims.en,r.prose.funding.en],unresolved:[r.prose.claims.en],reasons:eligible?[]:[reason],reason:eligible?r.prose.scope.en:reason,basicShares:r.sourceInputs.capital_known_june.common_shares_exact/1e6,allocationShares:a.conditional_june_common_shares,rows:[],inputs:{},optionDefinitions:[],mcdAllocation:a};
}
export function mcdSensitivity(d){const op=calculateMcdOperating(d);return {base:op.enterprise,normalized:op.enterprise,normalizationDelta:0,normalizedTerminalFCFFGrowth:op.terminal.fcffGrowth,normalizationLabel:incrementalRecord('MCD').prose.terminal.en,rates:[-.01,0,.01].map(shift=>{const next=structuredClone(d);next.annual.forEach(r=>r.wacc+=shift);next.terminal.wacc+=shift;try{return {waccShift:shift,wacc:next.terminal.wacc,enterprise:calculateMcdOperating(next).enterprise};}catch(e){return {waccShift:shift,wacc:next.terminal.wacc,enterprise:null,error:e.message};}})};}
